async deliver(job: DeliveryJob): Promise<DeliveryResult> {
  let attempt = job.attempts;

  while (true) {
    const result = await this.sender.send(job.payload);
    if (result.ok) return { status: "delivered" };

    attempt += 1;
    job.lastError = result.error;
    if (!this.policy.canRetry(attempt, job.lastError)) break;
    await this.policy.wait(attempt);
  }

  return { status: "failed", reason: "retry budget exhausted" };
}

export class RetryPolicy {
  constructor(private readonly maxAttempts = 3) {}

  canRetry(attempt: number, error?: DeliveryError): boolean {
    return error?.kind === "transient" && attempt < this.maxAttempts;
  }

  delay(attempt: number): number {
    return Math.min(1000 * 2 ** attempt, 8000);
  }
}

async send(payload: WebhookPayload): Promise<SendResult> {
  const response = await this.http.post(payload.url, payload.body);
  if (response.status === 429 || response.status >= 500) {
    return { ok: false, error: { kind: "transient", status: response.status } };
  }
  if (!response.ok) {
    return { ok: false, error: { kind: "permanent", status: response.status } };
  }
  return { ok: true };
}
